#!/usr/bin/env python3
from pathlib import Path
import json,html,re
r=Path(__file__).resolve().parents[1];e=html.escape
v=r/'verification'
runtime=json.loads((v/'final-runtime-audit.json').read_text()) if (v/'final-runtime-audit.json').exists() else {}
body='<div class="eyebrow">Evidence is scoped to a claim</div><h1>Verification evidence and limits</h1><p>Latest update: October 17, 2026. Earlier records retain their original dates. A passing compiler, lint, test or benchmark establishes different things. None grants independent acceptance or proves production readiness. Read the command, input and limitation together.</p>'
checks=json.loads((v/'checks.json').read_text()) if (v/'checks.json').exists() else {'checks':[]}
body+='<h2 id="baseline">Baseline checks</h2><p>Run <code>mise run verify</code> from the course folder. The recorded construction checks use an explicit shared target outside the portable folder. Full debug and incremental builds remain the default.</p><table><thead><tr><th>Check</th><th>Result</th><th>Evidence</th></tr></thead><tbody>'
for c in checks['checks']:body+=f'<tr><td>{e(c["name"])}</td><td>{"Passed" if c["passed"] else "Failed / requires attention"} · exit {c["exit_code"]}</td><td><a href="{e(c["log"])}">Exact command and output</a></td></tr>'
if not checks['checks']:body+='<tr><td>Final coordinated baseline</td><td>Construction check underway; see scoped logs below</td><td>Not yet claimed complete</td></tr>'
body+='</tbody></table><h2 id="boundaries">Boundary and advanced checks</h2><ul>'
entries=[('oct17-console-runtime.json','October 17 updated WASM runtime: offline recovery, empty state, replay, orders, watchlist/filter, retained identity, exact lookup/retry and pause/resume passed in Chrome.'),('oct17-consistency-review.json','Current acceptance preparation: corrected stale browser blockers in four lessons, the coverage map and review page; retained dated runtime/build scope and source hashes.'),('oct17-managed-wasm.json','Owner-managed wasm-bindgen 0.2.129: locked browser-client build, web binding generation, JavaScript syntax and WASM binary validation passed.'),('oct17-resumed.html','After the runtime update: current fuzz, false-oracle, Svelte unit/compiler/build/advisory and real HTTP passes; managed WASM build also passed; native Chrome file import and invalid-file rejection also passed.'),('oct17-audit.html','October 17 release, dependency, idiom and completion audit with current checks and explicit compatibility exceptions.'),('browser-live.html','Live Chrome reader, Rust console and Svelte checks; three UI corrections, print specimen and explicit import/export limits.'),('resume-finalization.html','Resumed audit: 13 coordinated checks, 218 native entries, eight progress-data tests and current source fingerprints.'),('continuation-followup.html','Requirement audit corrections: streaming search, live progress, tick input, native arguments, database targeting, shutdown and note-conflict detection.'),('cold-start-followup.html','Fresh source-copy launch and first-project path: directory, Python/mise and overwrite-preservation corrections.'),('services-spec-audit.html','Scheduler durable lease authority, post-lock time sampling, transaction rollback and real HTTP authorization checks.'),('advanced-boundary-audit.html','Exact parser limits, framed TCP boundaries, replication commit holes and scoped unsafe evidence language.'),('console-retry-review.html','Retained replay identities after uncertain responses, native model tests, WASM build and explicit cache paths.'),('mcp-followup.html','Direct Rust MCP workspace discovery, frozen metadata and targeted check succeeded; live session wrapper remains broken.'),('release-followup.html','Optimized arithmetic/unsafe tests and fresh portable checkpoint lockfile audit.'),('persistence-followup.html','Focused persistence audit, corrected path handling, corruption limits and regression evidence.'),('reader-followup.html','Reader source review: import persistence warnings and keyboard controls; real-browser gate remains open.'),('svelte-http-audit.json','Eight optional Svelte proxy/backend acceptance groups and 52 real HTTP requests; DOM interaction remains separate.'),('svelte-bridge.json','Optional Svelte 5 client: exact compatible versions, nine tests, compiler check, build and advisory scan; browser gate separate.'),('workbench-config-check.json','Invalid address rejection before journal I/O and native-path error handling; initial filesystem assumption corrected with evidence.'),('checkpoint-systems.html','Eight isolated system checkpoints: standalone locks, 41 tests and earlier-scope contracts.'),('early-checkpoints.json','Six complete foundational early milestones, tests and demonstration runs.'),('early-final-checkpoints.json','Foundational final-reference reconstructions and exact lockfiles.'),('rayon-comparison.html','Bounded serial, scoped-thread and Rayon CPU comparison with complete ordered outputs.'),('final-curriculum-audit.json','Author-team curriculum audit, requirement mappings, prerequisite gates and resolved findings.'),('final-runtime-audit.json',f'{len(runtime.get("checks",[]))} real HTTP acceptance groups and {len(runtime.get("requests",[]))} requests in the latest run: overload, crash recovery, cancellation, migration and duplicate identities.'),('core-labs-checks.json','Collections, conversions and interior-mutability laboratory tests, examples and compiler boundaries.'),('concurrency-labs-checks.json','Atomic reservation race, publication ordering and pinned deadline examples with intentional error evidence.'),('concurrency-labs-tests.log','Seven bounded concurrency/virtual-time unit tests.'),('oct17-resumed-final.json','Current 10,000-input parser fuzz campaign, expected false-oracle failure and resumed optional client checks.'),('fuzz-dependency-audit.json','Separate fuzz dependency lockfile advisory audit.'),('web-boundaries.json','Middleware order, extraction, authorization and browser-boundary HTTP tests.'),('performance-bridge-profile.json','Recorded layout/dispatch experiments and resource profiles, with workload and interpretation limits.'),('ui-selected-project.json','Selected learner/reference HTTP asset serving, WASM signatures and JavaScript syntax; no browser rendering claim.'),('ui-final-checkpoint.json','Fresh portable UI checkpoint, local path dependency reconstruction and locked WASM build.'),('services-checkpoints.json','Fifteen fresh service checkpoint reconstructions tested with their standalone lockfiles.'),('final-portability-audit.html','Portable extraction, source-copy refusal cases and dependency-path audit.'),('check-tests.log','Current native unit, integration targets and doctests; ignore-marked database tests are separate.'),('postgres-tests.log','Actual PostgreSQL issue and scheduler tests, migrations and authorization/transaction boundaries.'),('sqlx-offline.log','SQLx query metadata generation and offline verification, when recorded.'),('oct17-miri.log','Seven unsafe-component tests passed under nightly-2026-10-17; passing Miri is not a general proof of soundness.'),('ui-current-clippy.log','Current Leptos browser-target strict Clippy check.'),('ui-current-build.log','Current WASM and wasm-bindgen build; generated files are excluded from the portable package.'),('ui-model-tests.log','Five native UI contract regressions, including uncertain retries and sequence limits.'),('proxy-checks.json','Actual proxy admission and idle-socket recovery fixture.'),('backend-status-regressions.log','Definite rejection versus uncertain commit regressions.'),('services-final-checks.log','Isolated PostgreSQL and actual SQLx prepare/offline checks.'),('workbench-load.json','Isolated workbench load fixture with duplicate requests and state validation; no throughput guarantee.'),('benchmark-summary.json','Paired local performance variants, complete-state equivalence, environment and raw samples.'),('site-static.json','Local links, anchors, source correspondence and teaching-section checks; no rendering claim.'),('auxiliary-native-audit.json','Native dependency audit: no known vulnerabilities or warnings at the recorded database revision.'),('auxiliary-ui-audit.json','UI dependency audit: no known vulnerabilities; paste1.0.15 has an unmaintained advisory.'),('auxiliary-checks.html','Auxiliary verification summary: intentional compiler failures, no_std host tests, all16 scaffolds and dependency review.')]
for file,label in entries:
 if (v/file).exists():body+=f'<li><a href="{file}">{label}</a></li>'
body+='</ul><p>The UI dependency graph includes <code>paste 1.0.15</code>, marked unmaintained in RUSTSEC-2024-0436. The audit reports no patched release and no known vulnerability for this advisory. It is transitive through the pinned Leptos family; track an upstream replacement instead of blindly substituting a crate. See the exact dependency path in <a href="auxiliary-ui-paste-tree.log">the tree record</a>. An advisory scan is a snapshot of known reports, not a security proof.</p><p><a href="../benchmark-results.html">Read the benchmark method and interpretation in HTML</a>. “Faster” applies to the measured workload on the recorded host, not all workloads.</p><h2 id="browser">Browser checks: core flows and file import verified</h2><p>Localhost access is working. Live Chrome checks covered representative desktop/narrow reader layouts, keyboard navigation, clipboard copying, note persistence and stale-tab recovery, disclosure and six-page print output. The compiled Leptos console and optional Svelte client were exercised against an owned synthetic backend, including reconnect, retained-order retry and cancellation. Three UI issues were corrected and rechecked. <a href="browser-live.html">Read the live browser report</a> for exact scope and screenshots. Native Chrome file import, reload persistence, unsupported-version rejection, invalid-entry rejection and malformed-JSON rejection passed on October 17 without changing permissions. On October 17 an actual exported JSON file was read and its synthetic note and completion flag verified; see <a href="oct17-browser.json">the dated export and import evidence</a>. Earlier reports preserve their historical browser limitations.</p><h2 id="mcp">Tool access</h2><p>The active Rust MCP session wrapper still returns “Unexpected response type.” A direct JSON-RPC connection to the same configured 0.4.1 server successfully initialized, listed 33 tools, established the course workspace, returned frozen Cargo metadata and completed a targeted Cargo check. This narrows the unresolved fault to the live session/client integration boundary for those tested operations. The <a href="mcp-followup.html">MCP follow-up</a> preserves the exact protocol evidence. Other checks use Cargo CLI with explicit manifest paths; no successful session-wrapper call is claimed.</p><h2 id="snippets">Displayed source and intentional failures</h2><p>Source blocks marked with a file path are inserted directly during HTML generation. <a href="snippet-map.json">SHA-256 mappings</a> and the static checker verify correspondence. Short conceptual fragments and illustrative API shapes inside prose are not all standalone programs; they must not be represented as separately compiled artifacts. Doc examples, actual reference packages, dedicated compiler-error fixtures and their solutions have separate checks.</p><ul>'
for f in sorted(v.glob('*')):
 if f.suffix in ('.json','.log') and any(t in f.name for t in ('diagnostic','compile-fail','scaffold','exercise','patch001','specialization')):body+=f'<li><a href="{f.name}">{e(f.name)}</a></li>'
body+='</ul><h2>Disk accounting</h2><p>The <a href="disk-usage.json">disk measurement</a> separates authored content/source, generated UI and shared verification caches. One duplicate disposable native target was removed after checking for open files; the <a href="cache-cleanup.json">cleanup record</a> identifies exactly what was removed and preserved. Toolchain installations and unrelated global caches are excluded from these measurements, not claimed reclaimed. The portable archive excludes targets, generated UI, databases and learner work.</p><h2 id="limits">Deliberate scope and further work</h2><ul><li>The reader is a review draft. Independent review remains pending, and no learner competence is asserted.</li><li>Identity tokens are public loopback-only test fixtures. Production authentication, deployment hardening and an identity-provider integration are outside the implemented contract.</li><li>File persistence guarantees are explicitly bounded: the journal and KV labs do not establish every power-loss/filesystem behavior. The current database fixture passed against PostgreSQL 18.6 on October 17; earlier PostgreSQL 16.15 records retain their original scope.</li><li>Replication uses a deterministic teaching simulator with a fixed-leader contract, not a claimed Raft implementation or production consensus system.</li><li>Finite exhaustive properties, a 10,000-input fuzz smoke campaign, fault fixtures and recorded resource profiles are scoped evidence. They do not constitute exhaustive fuzz coverage, formal proofs, every allocator behavior or long-running SLO measurements.</li><li>The optional Svelte 5 bridge is a separate runnable read-only client with compiler/build and Node tests. Browser layout, refresh, filtering, cancellation and offline recovery have live Chrome evidence. It uses Vite, not SvelteKit. Embedded/FFI examples cover narrow host contracts, not flashed hardware or broad C-library safety.</li><li>Advanced assessment extensions deliberately ask for designs beyond the runnable baseline and reveal reference approaches separately. They are not silently counted as implemented product features.</li></ul><h2 id="inventory">Full evidence inventory</h2><ul>'
for f in sorted(v.iterdir()):
 if f.is_file() and f.name!='index.html':body+=f'<li><a href="{f.name}">{e(f.name)}</a></li>'
body+='</ul>'
(r/'authoring/evidence-fragment.html').write_text(body)
patch='<div class="eyebrow">Course patch 001</div><h1>Professional habits from the first project</h1><p>Applied to recommended source, checkpoints and explanations. Complexity grows with requirements; correctness, honest scope, explicit errors and reviewable evidence apply from the calculator onward. Deliberately broken exercises remain clearly labeled.</p><h2>Concrete findings and changes</h2>'
for f in sorted(v.glob('patch001-*.json')):
 d=json.loads(f.read_text());patch+=f'<section><h2>{e(f.stem.replace("patch001-",""))}</h2><p><a href="verification/{f.name}">Detailed audit and commands</a></p><ul>'
 for item in d.get('findings',d.get('changes',d.get('items',[]))):
  location=item.get('location',item.get('locations',''));fix=item.get('change',item.get('fix',item.get('resolution',item.get('correction','See detailed audit'))))
  patch+=f'<li><strong>{e(str(location))}</strong><p>{e(str(item.get("issue",item.get("finding","Audited"))))}</p><p>{e(str(fix))}</p></li>'
 patch+='</ul></section>'
patch+='<h2>Further requirement audit</h2><p>The <a href="verification/continuation-followup.html">continuation audit</a> reopens defects hidden by narrower passing checks: missing streaming search, live progress and tick input, native CLI argument handling, disposable database target guards, shutdown state, and stale-note overwrites. Its project reports record corrected source, teaching and verification.</p><h2>Continuation corrections</h2><p>The <a href="verification/cold-start-followup.html">cold-start audit</a> fixes the first learner-copy instructions and verifies no-overwrite behavior. The <a href="verification/services-spec-audit.html">service contract audit</a> corrects trust in caller-owned lease metadata, samples completion time after the database lock, and tests rollback and authorization. The <a href="verification/console-retry-review.html">console retry audit</a> retains one replay identity through uncertain outcomes. The <a href="verification/advanced-boundary-audit.html">advanced boundary audit</a> sharpens exact parser/protocol limits and corrects the distinction between tested evidence and proof.</p><h2>Additional adversarial follow-up</h2><p>The <a href="verification/persistence-followup.html">persistence follow-up</a> records a reproduced P06 path-retention defect and its verified fix, exact journal bounds and deliberately narrow corruption guarantees. The <a href="verification/release-followup.html">optimized-build review</a> adds arithmetic boundary evidence and checks every portable checkpoint dependency graph. The <a href="verification/reader-followup.html">reader review</a> corrects backup-data loss and keyboard-control defects with explicit browser limits. These reports list changed files and preserved before/after evidence.</p><h2>Changed files and teaching contract</h2><p>The <a href="generation-requirements.html">authoring contract</a> puts the professional standard immediately before the engineering rules and replaces the old beginner-versus-idiomatic review instruction. Canonical lesson changes are in authoring/foundations.json, systems.json, services.json, interface.json and prerequisites.json; rendered lessons and source hashes are regenerated together. Project audit records above identify the precise source and checkpoint files, including cases that already complied.</p><h2>First-project evidence</h2><p>The calculator uses checked integer arithmetic, rejects non-finite floating input and results, separates parsing from pure operations, handles CLI errors explicitly and propagates doctest failures through Result. Native-path handling avoids implicit non-Unicode argument panics. It uses the standard library because its scope does not need an async runtime, service layer or parsing framework. See <a href="lessons/stage-0/00-calculator.html">the calculator lesson</a> and <a href="verification/patch001-foundations-tests.log">the affected tests</a>.</p><h2>Verification and remaining review gaps</h2><p>Source-linked code is regenerated from the runnable files and checked for exact correspondence. Scoped tests, compiler diagnostics, database tests, WASM compilation, Miri and benchmarks have recorded commands in <a href="verification/index.html">the evidence index</a>. Core browser flows now have live Chrome evidence; file import, reload persistence, invalid-file rejection and saved export were verified on October 17. Independent review is pending. The patch does not turn compiler acceptance into a claim of universal correctness.</p><p><a href="review.html">The independent review checklist</a> now explicitly requires professional habits at first introduction, reinforced in every project with complexity justified by requirements.</p>'
(r/'authoring/patch-001.html').write_text(patch)
